import{_ as o,a0 as i,w as p,s,I as n,x as e,a1 as a,A as r,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"有助于组织治理的 5 项开源原则 | LCTT x X-CMD","titleTemplate":false,"description":"有助于组织治理的 5 项开源原则 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有助于组织治理的 5 项开源原则 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有助于组织治理的 5 项开源原则 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230411.2 ⭐️⭐️ 5 open source principles that help organizational governance","title":"有助于组织治理的 5 项开源原则","tag":"202306","desc":""},"relativePath":"202306/20230411.2 ⭐️⭐️ 5 open source principles that help organizational governance.md","filePath":"[post].md"}'),u={name:"202306/20230411.2 ⭐️⭐️ 5 open source principles that help organizational governance.md"};function m(f,t,g,b,h,x){const l=i("Link");return p(),s("div",null,[t[24]||(t[24]=n("h1",{id:"有助于组织治理的-5-项开源原则",tabindex:"-1"},[e("有助于组织治理的 5 项开源原则 "),n("a",{class:"header-anchor",href:"#有助于组织治理的-5-项开源原则","aria-label":"Permalink to “有助于组织治理的 5 项开源原则”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/09/165636wl15bs9nstjdb4wj.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"采用基于开源原则的组织治理可以引导你的组织降低成本，降低技术债务，增加团队协作，促进创新，最重要的是，推动你的组织共同前进。")],-1)),n("p",null,[t[1]||(t[1]=e("在我的职业生涯中，我很幸运地与许多不同规模的组织在各种项目上合作。所有这些项目的核心都是开源软件，而且大多数人都对开源社区做出了力所能及的回报。我最近在一个大型组织内从事一个使用开源软件的绿地项目。在项目的 MVP 阶段结束后，该组织的领导层很想知道是什么导致了项目的成功，以及他们如何将其应用到整个组织的其他团队中。经过思考，我发现我们团队的工作方式与开源社区和开发之间有相似之处。以下是对开源原则如何帮助组织节省资金、",-1)),a(l,{href:"https://enterprisersproject.com/article/2020/6/technical-debt-explained-plain-english?intcmp=7013a000002qLH8AAM"},{default:r(()=>[...t[0]||(t[0]=[e("减少技术债务",-1)])]),_:1}),t[2]||(t[2]=e(" 和打破内部孤岛的一些见解。",-1))]),t[27]||(t[27]=n("h3",{id:"_1、更好地使用预算",tabindex:"-1"},[e("1、更好地使用预算 "),n("a",{class:"header-anchor",href:"#_1、更好地使用预算","aria-label":"Permalink to “1、更好地使用预算”"},"​")],-1)),n("p",null,[t[4]||(t[4]=e("我最近在佛罗里达 Drupal 营地发表了关于 ",-1)),a(l,{href:"https://noti.st/johnpicozzi/thgcPs/think-locally-build-globally-how-drupal-is-powering-headless-omni-channel-web-platforms"},{default:r(()=>[...t[3]||(t[3]=[e("无头全渠道网络平台",-1)])]),_:1}),t[5]||(t[5]=e(" 的演讲。演讲中强调的主要好处之一是如何通过实施这种网络平台来节省资金。这个想法来自于开源软件的开发。一个组织内的不同小组可以利用他们的预算来为一个核心软件或平台贡献特性或功能。他们还可以与其他小组合作，集中资金开发更复杂的功能。当功能开发完成后，它将被添加到核心软件或平台中，供所有人使用。使用这种开源原则可以为组织内的团体提供互利。允许共享特性和功能，并集体从彼此的支出中获益，可以改善软件或平台。",-1))]),t[28]||(t[28]=d('<p>这种方法的另一个方面是可以节省开支，并允许持续改进，即对一个功能进行一次测试和开发，并重复使用它。在创建一个使用基于组件的设计系统作为起点的网络平台时，我们经常看到这种情况。该平台的用户可以重复使用其他用户开发的组件或功能。通常，这些都已经经过了无数次的测试，比如用户体验、可及性，甚至是安全测试。</p><p>这个简单的想法在许多组织中面临反对，因为个别团体觊觎和保护预算。团体不愿意放弃他们的预算来支持核心软件或平台。某些情况下，优先级和意见上的差异加剧了许多机构的孤岛化。</p><h3 id="_2、减少技术债务" tabindex="-1">2、减少技术债务 <a class="header-anchor" href="#_2、减少技术债务" aria-label="Permalink to “2、减少技术债务”">​</a></h3><p>许多机构努力减少技术债务。实施一个全面的核心软件或平台并使用开源原则，可以帮助减少技术债务。这可以通过允许开发团队充分考虑一个功能不仅对建立它的小组，而且对更广泛的组织有什么影响。这一点，加上与组织内其他小组的合作，可以帮助减少未来重建或增加功能的需要。</p><p>有时，由于内部竞争，组织在这种合作和思考方面会有困难。一些公司培养了一种文化，即第一个建立一个功能或提出一个想法会得到奖励。这可能会导致各小组不一起工作或分享想法，在组织内形成孤岛，大大阻碍了创新。</p><h3 id="_3、更快进入市场" tabindex="-1">3、更快进入市场 <a class="header-anchor" href="#_3、更快进入市场" aria-label="Permalink to “3、更快进入市场”">​</a></h3><p>我经常听到的一句话是“更快进入市场”。每个人都想更快、更容易地把他们的东西推出去。这通常是一个核心软件或平台的好处，因为内部团体可以重用现有的、经过测试和验证的特性和功能，而不是从头开始建立自己的功能。如果你的团队正在启动一个项目，而它可以从 80% 的完成度而不是 0% 的完成度开始，你会这样做吗？我想是的。现在再加上为其他用户增加所需功能的超级英雄感觉。这是一个双赢的结果！</p><h3 id="_4、发布兴奋点" tabindex="-1">4、发布兴奋点 <a class="header-anchor" href="#_4、发布兴奋点" aria-label="Permalink to “4、发布兴奋点”">​</a></h3><p>另一个可以帮助你的组织的伟大的开源原则是建立兴奋的发布时间表。当你的组织实施一个核心软件或平台时，用户会对更新的时间进行投资。一个发布时间表和路线图可以向他们传达这一点。这两个工具可以帮助用户对新功能感到兴奋，并相应地规划他们自己的路线图。这也有助于建立对其他团队的欣赏，以及对建立新功能的团队的自豪感。这可以统一一个组织，让组织有团队合作和成就感，同时提供结构和未来的计划。</p><h3 id="_5、一个核心团队和管理" tabindex="-1">5、一个核心团队和管理 <a class="header-anchor" href="#_5、一个核心团队和管理" aria-label="Permalink to “5、一个核心团队和管理”">​</a></h3><p>我发现你需要两个关键项目来克服上述障碍，并在你的组织内成功应用开源原则。这就是： 一个核心团队和坚实的组织管理。一个核心团队将允许一个小组来维护和管理你的组织的核心软件或平台。它将支持该解决方案，并确保明智地增加新的特性和功能。这个团队可以帮助减少内部团队的成本，并告知各组路线图的功能。核心团队需要得到强大的组织治理的支持。这种治理将为组织内的小组提供一个共同的方向和组织支持，以取得成功。这种组织治理可以在几个方面模仿开源的治理和原则。最基本和最高级别的原则是社区和为共同目标而工作的理念。</p><h3 id="开放式领导" tabindex="-1">开放式领导 <a class="header-anchor" href="#开放式领导" aria-label="Permalink to “开放式领导”">​</a></h3>',12)),n("p",null,[t[7]||(t[7]=e("采用基于 ",-1)),a(l,{href:"https://opensource.com/article/23/4/open-leadership-through-change"},{default:r(()=>[...t[6]||(t[6]=[e("开源原则",-1)])]),_:1}),t[8]||(t[8]=e(" 的组织治理可以引导你的组织降低成本，降低技术债务，增加团队协作，促进创新，最重要的是，推动你的组织共同前进。",-1))]),t[29]||(t[29]=n("p",null,[n("em",null,"（题图：MJ/be676bca-3cd3-4c21-9c6a-6cc5911c9c04）")],-1)),t[30]||(t[30]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),a(l,{href:"https://opensource.com/article/23/4/open-source-principals-organizational-governance"},{default:r(()=>[...t[9]||(t[9]=[e("https://opensource.com/article/23/4/open-source-principals-organizational-governance",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),a(l,{href:"https://opensource.com/users/johnpicozzi"},{default:r(()=>[...t[11]||(t[11]=[e("John E. Picozzi",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),a(l,{href:"https://github.com/lkxed/"},{default:r(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),a(l,{href:"https://github.com/geekpi"},{default:r(()=>[...t[13]||(t[13]=[e("geekpi",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),a(l,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const P=o(u,[["render",m]]);export{C as __pageData,P as default};
